INSERT INTO public.available_slots(id,staff_id,appointment_type_id,start_time,end_time,max_bookings) VALUES ('55555555-5555-4555-8555-555555555555','33333333-3333-4333-8333-333333333333','44444444-4444-4444-8444-444444444444','2099-01-01 10:00:00+00','2099-01-01 10:30:00+00',2);
DO $$ DECLARE first_visit public.appointments; second_visit public.appointments; rejected boolean:=false; BEGIN
 first_visit:=public.create_booked_appointment('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555','44444444-4444-4444-8444-444444444444','2099-01-01 10:00:00+00',null);
 IF first_visit.staff_id <> '33333333-3333-4333-8333-333333333333' OR first_visit.start_time <> '2099-01-01 10:00:00+00'::timestamptz THEN RAISE EXCEPTION 'Provider/time mismatch'; END IF;
 second_visit:=public.create_booked_appointment('22222222-2222-4222-8222-222222222222','55555555-5555-4555-8555-555555555555','44444444-4444-4444-8444-444444444444','2099-01-01 10:00:00+00',null);
 BEGIN PERFORM public.create_booked_appointment('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555','44444444-4444-4444-8444-444444444444','2099-01-01 10:00:00+00',null); EXCEPTION WHEN raise_exception THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Overbooking permitted'; END IF;
 PERFORM public.transition_appointment(first_visit.id,'11111111-1111-4111-8111-111111111111','cancelled');
 PERFORM public.transition_appointment(first_visit.id,'11111111-1111-4111-8111-111111111111','cancelled');
 IF (SELECT current_bookings FROM public.available_slots WHERE id='55555555-5555-4555-8555-555555555555') <> 1 THEN RAISE EXCEPTION 'Repeated cancellation corrupted capacity'; END IF;
 rejected:=false;
 BEGIN PERFORM public.transition_appointment(second_visit.id,'11111111-1111-4111-8111-111111111111','cancelled'); EXCEPTION WHEN raise_exception THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Unauthorized cancellation permitted'; END IF;
 rejected:=false;
 BEGIN PERFORM public.create_booked_appointment('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555','44444444-4444-4444-8444-444444444444','2099-01-01 11:00:00+00',null); EXCEPTION WHEN raise_exception THEN rejected:=true; END;
 IF NOT rejected THEN RAISE EXCEPTION 'Time mismatch accepted'; END IF;
