SELECT set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true),set_config('request.jwt.claim.role','authenticated',true);
DO $$ DECLARE denied boolean:=false; BEGIN
 IF (SELECT count(*) FROM public.appointments) <> 1 THEN RAISE EXCEPTION 'Patient sees another patient appointments'; END IF;
 IF (SELECT count(*) FROM public.users) <> 1 THEN RAISE EXCEPTION 'Patient sees another profile'; END IF;
 BEGIN UPDATE public.users SET role='admin' WHERE id='11111111-1111-4111-8111-111111111111'; EXCEPTION WHEN insufficient_privilege OR raise_exception THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Role escalation permitted'; END IF;
 denied:=false;
 BEGIN PERFORM public.create_booked_appointment('11111111-1111-4111-8111-111111111111','55555555-5555-4555-8555-555555555555','44444444-4444-4444-8444-444444444444','2099-01-01 10:00:00+00',null); EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Browser can impersonate RPC actor'; END IF;
 denied:=false;
 BEGIN PERFORM access_token FROM public.video_visits; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'Video tokens readable by browser'; END IF;
END $$;
